def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return min(my_status['budget'], 1.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    current_bid = DAILY_SALARY * 0.6

    if my_status['hp'] <= 2:
        current_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        current_bid = DAILY_SALARY * 0.75

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2:
        if my_status['hp'] <= 3:
            current_bid = DAILY_SALARY * 1.1
        else:
            current_bid = DAILY_SALARY * 0.9
    elif remaining_days <= 5:
        current_bid *= 1.05

    estimated_total_demand = (num_alive_opponents + 1) * WATER_REQ
    if day_context['supply'] < estimated_total_demand:
        scarcity_ratio = estimated_total_demand / day_context['supply']
        current_bid *= min(scarcity_ratio * 0.8, 1.3)

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3:
                current_bid = max(current_bid, highest_prev_bid + 1.0)
            else:
                current_bid = max(current_bid, highest_prev_bid + DAILY_SALARY * 0.2)
        elif highest_prev_bid < DAILY_SALARY * 0.5:
            if my_status['hp'] > 3:
                current_bid = min(current_bid, highest_prev_bid + 5.0)
            else:
                current_bid = max(current_bid, highest_prev_bid + 1.0)
        else:
            current_bid = max(current_bid, highest_prev_bid + 1.5)

    final_bid = min(my_status['budget'], current_bid)

    if my_status['hp'] < EPISODE_DAYS:
        final_bid = max(final_bid, 1.0)
    else:
        if remaining_days == 0 and my_status['budget'] > DAILY_SALARY:
            final_bid = min(my_status['budget'], DAILY_SALARY * 0.5)
        else:
            final_bid = min(my_status['budget'], 0.1)

    return float(max(final_bid, 0.01))

def get_bid(day_context, my_status, opponents_status):
    SALARY = 150
    # Gather yesterday's bids from alive opponents
    prev_bids = []
    for opp in opponents_status.values():
        if opp['alive'] and opp.get('previous_trace') and opp['previous_trace'].get('bid') is not None:
            prev_bids.append(opp['previous_trace']['bid'])
    if prev_bids:
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        avg_prev = SALARY * 0.6
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']
    if no_water > 0 or hp <= 3:
        bid = min(budget, max(avg_prev + 5, SALARY * 0.8))
    else:
        bid = min(budget, max(avg_prev - 10, SALARY * 0.4))
    bid = max(0, min(budget, bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents and yesterday bids
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents, just bid to secure enough water
    if not alive_opps:
        # Aim for a modest share; cap by budget
        return min(my_status['budget'], DAILY_SALARY * 0.45)

    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Use yesterday's highest and second-highest bids to infer aggressiveness
    highest = max(yesterday_bids) if yesterday_bids else 0.0
    # If Cindy died with low bids, the low-bid crowd likely loses; if Bob survived with high bids, match near her level.

    # Tight supply means more competition for the same water -> bid higher
    # supply is float; use thresholds without indexing
    tight = supply <= (MIN_SUPPLY + 2.0)  # <=17
    mid = supply <= (MIN_SUPPLY + 6.0)   # <=21

    # Base bid levels inferred from yesterday meta
    # Bob avg ~163, Alex max ~235 (died), David avg ~121 (survived)
    target = 0.0
    if tight:
        # Try to beat the likely leader without going to Alex's extreme
        # If yesterday highest was very high, bid slightly below it to avoid overpaying
        if highest >= DAILY_SALARY * 1.05:  # ~147
            target = min(highest - 5.0, DAILY_SALARY * 1.25)  # ~175
        else:
            target = DAILY_SALARY * 1.15  # ~161
    elif mid:
        # Moderate competition
        if highest >= DAILY_SALARY * 1.05:
            target = min(highest - 15.0, DAILY_SALARY * 1.05)  # ~147
        else:
            target = DAILY_SALARY * 0.85  # ~119
    else:
        # Plenty of supply: conserve budget; still ensure we get enough water
        if highest >= DAILY_SALARY * 1.05:
            target = min(highest - 25.0, DAILY_SALARY * 0.75)  # ~105
        else:
            target = DAILY_SALARY * 0.6  # ~84

    # Risk adjustment based on our hp and no_water_days
    hp = my_status.get('hp', 0)
    no_water_days = my_status.get('no_water_days', 0)
    budget = my_status.get('budget', 0)

    # If we are close to dying or already had no-water days, increase bids
    if hp <= 2:
        target = max(target, DAILY_SALARY * 1.35)
    elif hp <= 4:
        target = max(target, DAILY_SALARY * 1.15)

    if no_water_days >= 2:
        target = max(target, DAILY_SALARY * 1.1)

    # Final cap by budget; never bid negative
    if budget <= 0:
        return 0.0
    if target < 0:
        target = 0.0

    # Ensure we don't overshoot budget; also keep within reasonable range
    bid = min(budget, target)
    return float(bid)
